  {marketError&&<div className="mpx-error" role="alert"><p className="ds-error">Couldn’t load listings.</p><button type="button" className="ds-link" onClick={()=>setMarketRetry(value=>value+1)}><RefreshCw size={15}/> Try again</button>{anyFilter&&<button type="button" className="ds-link" onClick={clearFilters}>Clear filters</button>}</div>}
  {net.error&&<div className="mpx-error" role="alert"><p className="ds-error">Couldn’t load your marketplace info.</p><button type="button" className="ds-link" onClick={()=>void net.refresh()}><RefreshCw size={15}/> Try again</button></div>}
  {!pageCurrent&&!marketError&&<LoadingState message="Loading listings…"/>}
  {!net.error&&!marketError&&pageCurrent&&!shownListings.length&&<EmptyState title={emptyTitle} message={anyFilter?'Try another search, or clear your filters.':'Got a comic to sell? List it in a few minutes.'} secondary={anyFilter?{label:'Clear filters',onClick:clearFilters}:{label:'Sell a comic',onClick:()=>openEditor('single','fixed')}}/>}
